// =========================================================================
// US-B3 : source découplée du type d'événement.
// On lit la table générique `declencheurs` (type='evenement', actif) ; chaque
// déclencheur porte l'événement embarqué -> on délègue le calcul de date à la
// logique existante (CLAUDE.md §8), strictement inchangée. Au MVP, seuls des
// déclencheurs type 'evenement' existent : l'ensemble traité est identique à
// l'ancienne source `evenements` (parité vérifiée).
//
// US-A1 : on respecte la fréquence choisie par l'utilisateur
// (evenements.frequence, ex 'j30_j14_j7') : un jalon n'est émis que s'il y figure.
// =========================================================================

const SEUILS = [30, 14, 7];

const aujourdhui = new Date();
aujourdhui.setHours(0, 0, 0, 0);

function niemeDimanche(annee, mois, n) {
  const premier = new Date(annee, mois, 1);
  const decalage = (7 - premier.getDay()) % 7;
  const jour = 1 + decalage + (n - 1) * 7;
  return new Date(annee, mois, jour);
}

function prochaineOccurrence(mois, jour) {
  const annee = aujourdhui.getFullYear();
  let d = new Date(annee, mois, jour);
  d.setHours(0, 0, 0, 0);
  if (d < aujourdhui) d = new Date(annee + 1, mois, jour);
  return d;
}

function prochainDimancheCalcule(calculer) {
  const annee = aujourdhui.getFullYear();
  let d = calculer(annee);
  d.setHours(0, 0, 0, 0);
  if (d < aujourdhui) d = calculer(annee + 1);
  return d;
}

function dateProchaineOccurrence(ev) {
  switch (ev.type) {
    case 'anniversaire': {
      const dn = new Date(ev.proches.date_naissance);
      return prochaineOccurrence(dn.getMonth(), dn.getDate());
    }
    case 'noel':
      return prochaineOccurrence(11, 25);
    case 'saint_valentin':
      return prochaineOccurrence(1, 14);
    case 'fete_meres':
      return prochainDimancheCalcule((a) => niemeDimanche(a, 5, 1));
    case 'fete_peres':
      return prochainDimancheCalcule((a) => niemeDimanche(a, 5, 3));
    case 'fete_grands_parents':
      return prochainDimancheCalcule((a) => niemeDimanche(a, 9, 1));
    case 'autre': {
      if (!ev.date_fixe) return null;
      const df = new Date(ev.date_fixe);
      return prochaineOccurrence(df.getMonth(), df.getDate());
    }
    default:
      return null;
  }
}

const MS_PAR_JOUR = 1000 * 60 * 60 * 24;
const sortie = [];

for (const item of $input.all()) {
  const decl = item.json;
  const ev = decl.evenements; // événement embarqué via le déclencheur
  if (!ev || ev.actif === false) continue;

  const dateEv = dateProchaineOccurrence(ev);
  if (!dateEv) continue;

  const joursRestants = Math.round((dateEv - aujourdhui) / MS_PAR_JOUR);
  if (!SEUILS.includes(joursRestants)) continue;

  // US-A1 : la fréquence de l'événement doit inclure ce jalon (j30/j14/j7).
  const frequence = ev.frequence || 'j30_j14_j7';
  const jalon = 'j' + joursRestants;
  if (!frequence.split('_').includes(jalon)) continue;

  sortie.push({
    json: {
      ...ev,
      declencheur_id: decl.id, // pour journaliser dans interactions (à venir)
      jours_restants: joursRestants,
      date_evenement: dateEv.toISOString().slice(0, 10),
    },
  });
}

return sortie;

// =========================================================================
// Assemble l'e-mail et le payload de log à partir de :
//   - l'événement enrichi (node "Filtre J-30 / J-14 / J-7"),
//   - les propositions scorées (node "Edge Function matching"),
//   - les détails produits (node "Supabase — détails produits"),
//   - l'e-mail du destinataire (node "Supabase — e-mail utilisateur (RPC)").
//
// On RÉ-ALIGNE les produits sur l'ordre/score des propositions, on construit le
// HTML du mail (template CLAUDE.md §9) et le tableau `lignes_log` prêt pour
// l'INSERT dans `propositions`.
// =========================================================================

const ev = $('Filtre J-30 / J-14 / J-7').item.json;
const propositions = $('Edge Function matching').item.json.propositions || [];
const produits = $('Supabase — détails produits').item.json.data || $('Supabase — détails produits').item.json || [];

// E-mail résolu via la RPC `email_utilisateur` (auth.users). PostgREST renvoie
// la chaîne JSON brute (ex: "user@exemple.fr") ou null si introuvable ; on
// retombe sur RESEND_FALLBACK_TO le cas échéant.
const rpcEmail = $('Supabase — e-mail utilisateur (RPC)').item.json;
const emailUtilisateur = (typeof rpcEmail === 'string' ? rpcEmail : (rpcEmail?.data ?? rpcEmail)) || '';

// Index produit par id pour ré-aligner sur l'ordre des propositions.
const parId = {};
for (const p of produits) parId[p.id] = p;

// Libellés lisibles des types d'événement.
const LIBELLES = {
  anniversaire: 'Anniversaire',
  noel: 'Noël',
  fete_meres: 'Fête des mères',
  fete_peres: 'Fête des pères',
  fete_grands_parents: 'Fête des grands-parents',
  saint_valentin: 'Saint-Valentin',
  autre: 'Événement',
};
const libelleEvenement = LIBELLES[ev.type] || 'Événement';

// Prénoms : utilisateur (profils) et proche.
const prenomUtilisateur = ev.proches?.profils?.prenom || '';
const prenomProche = ev.proches?.prenom || '';
const jours = ev.jours_restants;

// Formatage prix : « 25–40 € » ou « 25 € » si min == max.
function formatPrix(p) {
  const min = p.prix_min != null ? Math.round(p.prix_min) : null;
  const max = p.prix_max != null ? Math.round(p.prix_max) : null;
  if (min != null && max != null) return min === max ? `${min} €` : `${min}–${max} €`;
  if (min != null) return `dès ${min} €`;
  if (max != null) return `jusqu'à ${max} €`;
  return '';
}

// Lignes (texte + HTML) dans l'ordre des propositions, max 5.
const lignesHtml = [];
const lignesLog = [];
for (const prop of propositions.slice(0, 5)) {
  const produit = parId[prop.produit_id];
  if (!produit) continue;
  const prix = formatPrix(produit);
  lignesHtml.push(
    `<li style="margin:8px 0"><a href="${produit.url_produit}">${produit.nom}</a>${prix ? ` — <strong>${prix}</strong>` : ''}</li>`
  );
  lignesLog.push({
    proche_id: ev.proche_id,
    evenement_id: ev.id,
    produit_id: prop.produit_id,
    score: prop.score,
  });
}

const lienApp = $env.APP_URL || 'https://giftmatch.app';

const sujet = `🎁 Idées cadeaux pour ${prenomProche} — ${libelleEvenement} dans ${jours} jours`;

const html = `
<div style="font-family:system-ui,Arial,sans-serif;color:#222;max-width:560px">
  <p>Bonjour ${prenomUtilisateur},</p>
  <p><strong>${libelleEvenement}</strong> de ${prenomProche} approche !<br>Voici 5 idées sélectionnées pour lui/elle :</p>
  <ul style="list-style:none;padding:0">${lignesHtml.join('')}</ul>
  <p><a href="${lienApp}">Voir d'autres idées →</a></p>
</div>`.trim();

return [{
  json: {
    sujet,
    html,
    destinataire_email: emailUtilisateur || $env.RESEND_FALLBACK_TO || '',
    lignes_log: lignesLog,
    a_envoyer: lignesLog.length > 0,
  },
}];
